<?php
namespace App\Http\Controllers\Auth;
use App\Http\Controllers\Controller;use App\Services\MramSmsService;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;use Illuminate\Validation\ValidationException;
class PhoneVerificationController extends Controller { public function send(Request $request,MramSmsService $sms): RedirectResponse { $user=$request->user();if($user->phone_verified_at)return back();$code=(string)random_int(100000,999999);try{$sms->send($user->phone,"Your ".config('app.name')." verification code is {$code}. It expires in 10 minutes.");}catch(\Throwable $e){report($e);throw ValidationException::withMessages(['phone_verification'=>'Verification code could not be sent. Please try again.']);}$user->forceFill(['phone_verification_code'=>Hash::make($code),'phone_verification_expires_at'=>now()->addMinutes(10)])->save();return back()->with('status','phone-code-sent'); } public function verify(Request $request): RedirectResponse { $data=$request->validate(['code'=>['required','digits:6']]);$user=$request->user();if(!$user->phone_verification_code||!$user->phone_verification_expires_at||now()->greaterThan($user->phone_verification_expires_at)||!Hash::check($data['code'],$user->phone_verification_code))throw ValidationException::withMessages(['code'=>'The verification code is invalid or expired.']);$user->forceFill(['phone_verified_at'=>now(),'phone_verification_code'=>null,'phone_verification_expires_at'=>null])->save();return back()->with('status','phone-verified'); } }